        for start, end in [(date(2024,1,31),date(2024,2,29)),(date(2025,1,31),date(2025,2,28)),(date(2025,12,31),date(2026,1,31)),(date(2026,3,31),date(2026,4,30)),(date(2026,5,15),date(2026,6,15)),(date(2000,1,30),date(2000,2,29)),(date(1900,1,30),date(1900,2,28))]:
            self.assertEqual(next_renewal(start), end)

